const geminiResponse = $input.first().json;

// Extract the raw text from Gemini's nested response structure
const rawText = geminiResponse.candidates?.[0]?.content?.parts?.[0]?.text;

if (!rawText) {
  throw new Error('Gemini returned empty response. Check your API key and request format.');
}

// Clean accidental markdown fences that Gemini sometimes adds
const cleaned = rawText
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

let screening;
try {
  screening = JSON.parse(cleaned);
} catch (e) {
  throw new Error(`Gemini returned invalid JSON. Raw response: ${rawText}`);
}

// Validate required fields
if (!screening.score || !screening.recommendation) {
  throw new Error(`Gemini JSON missing required fields. Got: ${JSON.stringify(screening)}`);
}

// Merge with applicant data from the previous Code node
const prev = $('Code — Extract & Prepare CV Data').first().json;

return [{
  json: {
    ...prev,
    ai_score: Number(screening.score),
    ai_strengths: screening.strengths || 'Not provided',
    ai_gaps: screening.gaps || 'Not provided',
    ai_recommendation: screening.recommendation,
    gemini_raw: rawText
  }
}];

